using AppKit;
using Shiny;
using ShinyNotch.Platform;

namespace ShinyNotch.MacOS;

/// <summary>
/// The general pasteboard. AppKit says nothing when it changes, so its change count is read twice a
/// second - one integer, no contents, until it moves.
/// </summary>
[Singleton]
sealed class MacClipboardWatcher(IDispatcher dispatcher) : IClipboardWatcher
{
    static readonly TimeSpan PollEvery = TimeSpan.FromMilliseconds(500);

    /// <summary>
    /// The nspasteboard.org markers: password managers flag what they copy as concealed or transient,
    /// and "auto-generated" is a copy no person made. None of it belongs in a history.
    /// </summary>
    static readonly string[] Skipped =
    [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        // Files copied in Finder: their names come along as text, but the file tray is for files.
        "public.file-url"
    ];

    IDispatcherTimer? timer;
    nint lastCount;

    public event EventHandler<string>? TextCopied;

    public void Start()
    {
        if (this.timer != null)
            return;

        // What's on the clipboard at launch isn't a new copy.
        this.lastCount = NSPasteboard.GeneralPasteboard.ChangeCount;
        this.timer = dispatcher.CreateTimer();
        this.timer.Interval = PollEvery;
        this.timer.Tick += (_, _) => this.Poll();
        this.timer.Start();
    }

    void Poll()
    {
        var board = NSPasteboard.GeneralPasteboard;
        var count = board.ChangeCount;
        if (count == this.lastCount)
            return;
        this.lastCount = count;

        var types = board.Types ?? [];
        if (types.Any(t => Skipped.Contains(t)))
            return;

        if (board.GetStringForType(NSPasteboard.NSPasteboardTypeString) is { Length: > 0 } text)
            this.TextCopied?.Invoke(this, text);
    }

    public void SetText(string text)
    {
        var board = NSPasteboard.GeneralPasteboard;
        board.ClearContents();
        board.SetStringForType(text, NSPasteboard.NSPasteboardTypeString);
    }
}
